import pandas as pd
import seaborn as sns
import numpy as np
import ast

def task_func(csv_file):
    import matplotlib.pyplot as plt

    def parse_list(value):
        if pd.isna(value):
            return []
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
        if isinstance(value, str):
            try:
                parsed = ast.literal_eval(value)
                if isinstance(parsed, list):
                    return parsed
                if isinstance(parsed, tuple):
                    return list(parsed)
                return [parsed]
            except (ValueError, SyntaxError):
                return [value]
        return [value]

    df = pd.read_csv(csv_file)

    if "list" not in df.columns or "email" not in df.columns:
        raise ValueError("CSV file must contain 'email' and 'list' columns.")

    df["list"] = df["list"].apply(parse_list)

    df["sum"] = df["list"].apply(lambda x: np.sum(x) if len(x) > 0 else np.nan)
    df["mean"] = df["list"].apply(lambda x: np.mean(x) if len(x) > 0 else np.nan)
    df["std"] = df["list"].apply(lambda x: np.std(x, ddof=1) if len(x) > 1 else np.nan)

    fig, ax = plt.subplots()
    sns.histplot(df["mean"].dropna(), ax=ax)
    ax.set_xlabel("Mean")
    ax.set_ylabel("Count")
    ax.set_title("Histogram of Mean Values")

    return df[["email", "list", "sum", "mean", "std"]], ax
